import re
from datetime import date
def candidate_date(value: object) -> date | None:
    if value is None:
        return None
    if not isinstance(value,str) or re.fullmatch(r"[0-9]{4}-[0-9]{2}-[0-9]{2}",value) is None:
        raise ValueError("YYYY-MM-DD required")
    return date.fromisoformat(value)

def contract_text(value: object) -> str:
    if not isinstance(value,str) or not 1<=len(value)<=200 or not value.strip() or value!=value.strip():
        raise ValueError("bounded unpadded nonblank text required")
    return value

FIELDS = ('supplier_name', 'product', 'quantity', 'unit', 'unit_price', 'currency', 'delivery_date', 'payment_terms')

def key_issues(candidate: dict) -> tuple[list[str],list[str]]:
    if not isinstance(candidate,dict) or any(not isinstance(k,str) for k in candidate):
        raise ValueError("string-keyed object required")
    keys=set(candidate)
    return sorted(set(FIELDS)-keys),sorted(keys-set(FIELDS))

def unique_pairs(pairs: list[tuple[str,object]]) -> dict[str,object]:
    result={}
    for key,value in pairs:
        if key in result:
            raise ValueError("duplicate JSON key")
        result[key]=value
    return result

