import json
from decimal import Decimal
def candidate_object(raw: str, byte_limit: int=32768) -> dict:
    if not isinstance(raw,str) or type(byte_limit) is not int or byte_limit<0:
        raise ValueError("invalid input")
    try:
        if len(raw.encode("utf-8"))>byte_limit:
            raise ValueError("too large")
        def pairs(items):
            result={}
            for key,value in items:
                if key in result:
                    raise ValueError("duplicate key")
                result[key]=value
            return result
        def constant(value):
            raise ValueError("non-standard constant")
        parsed=json.loads(raw,object_pairs_hook=pairs,parse_constant=constant,parse_float=Decimal)
        if not isinstance(parsed,dict):
            raise ValueError("object root required")
        return parsed
    except (UnicodeEncodeError,json.JSONDecodeError,RecursionError) as error:
        raise ValueError("invalid candidate JSON") from error

def fits_utf8(text: str, limit: int) -> bool:
    if not isinstance(text,str) or type(limit) is not int or limit<0:
        raise ValueError("string and nonnegative byte limit required")
    try:
        return len(text.encode("utf-8"))<=limit
    except UnicodeEncodeError:
        return False

def labelled_fields(text: str) -> dict[str,str]:
    allowed={"supplier","product","quantity","unit price","delivery date","payment terms"}
    fields={}
    for line in text.splitlines():
        if not line.strip() or line.strip()=="Purchase confirmation":
            continue
        if ":" not in line:
            raise ValueError("unexpected line")
        key,value=line.split(":",1)
        key=key.strip().casefold();value=value.strip()
        if key not in allowed or key in fields or not value:
            raise ValueError("invalid label")
        fields[key]=value
    if not allowed-{"delivery date"}<=fields.keys():
        raise ValueError("missing required source fact")
    return fields

import re
from decimal import Decimal
def source_quantity(text: str) -> tuple[Decimal,str]:
    if not isinstance(text,str):
        raise ValueError("text required")
    pattern=r"([1-9][0-9]{0,2}(?:,[0-9]{3})+(?:\.[0-9]+)?|(?:0|[1-9][0-9]*)(?:\.[0-9]+)?) (kg|ea)"
    match=re.fullmatch(pattern,text)
    if match is None:
        raise ValueError("quantity grammar")
    amount=Decimal(match[1].replace(",",""))
    if amount<=0:
        raise ValueError("positive quantity required")
    return amount,match[2]

import re
from decimal import Decimal
def source_price(text: str) -> tuple[Decimal,str]:
    if not isinstance(text,str):
        raise ValueError("text required")
    match=re.fullmatch(r"USD ((?:0|[1-9][0-9]*)(?:\.[0-9]+)?) per (kg|ea)",text)
    if match is None:
        raise ValueError("price grammar")
    return Decimal(match[1]),match[2]

from decimal import Decimal
def same_amount(a: Decimal,b: Decimal) -> bool:
    if not isinstance(a,Decimal) or not isinstance(b,Decimal) or not a.is_finite() or not b.is_finite():
        raise ValueError("finite Decimal operands required")
    return a==b

