    return json.dumps({"document":document},ensure_ascii=False,sort_keys=True,separators=(",",":"),allow_nan=False)

import json
from hashlib import sha256
def request_digest(messages,schema: str,prompt_version: str,schema_version: str) -> str:
    payload={"messages":messages,"schema":schema,"prompt_version":prompt_version,"schema_version":schema_version}
    canonical=json.dumps(payload,sort_keys=True,separators=(",",":"),ensure_ascii=False,allow_nan=False)
    return sha256(canonical.encode("utf-8")).hexdigest()

def call_cap(transport_attempts: int=2,repair_attempts: int=1) -> int:
    if type(transport_attempts) is not int or not 1<=transport_attempts<=3 or type(repair_attempts) is not int or not 0<=repair_attempts<=2:
        raise ValueError("invalid recovery cap")
    return transport_attempts*(repair_attempts+1)

def attempt_kind(repair_round: int,transport_index: int) -> str:
    if type(repair_round) is not int or repair_round<0 or type(transport_index) is not int or transport_index<0:
        raise ValueError("nonnegative integer indices required")
    return "transport_retry" if transport_index else "validation_repair" if repair_round else "initial"

def recovery_trace(events: list[str]) -> tuple[str,str|None,list[str]]:
    kinds=[]
    index=0
    for repair_round in range(2):
        for transport_index in range(2):
            if index==len(events):
                return "needs_review","SCRIPT_EXHAUSTED",kinds
            event=events[index];index+=1
            if not isinstance(event,str) or event not in {"transport","schema","evidence","valid","identity","date_absent"}:
                raise ValueError("unknown event")
            kinds.append("transport_retry" if transport_index else "validation_repair" if repair_round else "initial")
            if event=="transport":
                if transport_index==1:
                    return "needs_review","TRANSPORT_EXHAUSTED",kinds
                continue
            if event=="valid":
                return "valid",None,kinds
            if event in {"identity","date_absent"}:
                return "needs_review","MODEL_IDENTITY_MISMATCH" if event=="identity" else "DELIVERY_DATE_ABSENT",kinds
            break
        if repair_round==1:
            return "needs_review","REPAIR_EXHAUSTED",kinds
    raise AssertionError("unreachable")

def support_metrics(results: list[tuple[bool,bool]]) -> dict:
    for row in results:
        if not isinstance(row,(tuple,list)) or len(row)!=2 or any(type(x) is not bool for x in row) or (row[1] and not row[0]):
            raise ValueError("invalid validation result")
    total=len(results)
    schema=sum(row[0] for row in results)
    supported=sum(row[1] for row in results)
    return {"total":total,"schema_passed":schema,"evidence_supported":supported,
            "schema_rate":schema/total if total else None,"support_rate":supported/total if total else None}

